from abc import ABC, abstractmethod

from pox.error import RuntimeError
from pox.interpreter.environment import Environment

class ReturnException(Exception):
    def __init__(self, value):
        self.value = value

class PoxCallable(ABC):
    @abstractmethod
    def arity(self):
        pass

    @abstractmethod
    def call(self, interpreter, arguments):
        pass

class PoxFunction(PoxCallable):
    def __init__(self, closure, declaration, initializer):
        self.closure = closure
        self.declaration = declaration
        self.initializer = initializer

    def __str__(self):
        return f'<fn {self.declaration.name.lexeme}>'

    def arity(self):
        return len(self.declaration.params)

    def call(self, interpreter, arguments):
        environment = Environment(self.closure)

        for i, param in enumerate(self.declaration.params):
            environment.define(param.lexeme, arguments[i])

        try:
            interpreter.execute_block(self.declaration.body, environment)
        except ReturnException as return_value:
            if not self.initializer:
                return return_value.value

        if self.initializer:
            return self.closure.get_at(0, 'this')

    def bind(self, instance):
        environment = Environment(self.closure)
        environment.define('this', instance)

        return PoxFunction(environment, self.declaration, self.initializer)

class PoxInstance:
    def __init__(self, pclass):
        self.fields = {}
        self.pclass = pclass

    def __str__(self):
        return f'<class instance {self.pclass.name}>'

    def get(self, name):
        if name.lexeme in self.fields:
            return self.fields[name.lexeme]

        if method := self.pclass.find_method(name.lexeme):
            return method.bind(self)

        raise RuntimeError(name, f'undefined property \'{name.lexeme}\'')

    def set(self, name, value):
        self.fields.update({name.lexeme: value})

class PoxClass(PoxCallable):
    def __init__(self, name, superclass, methods):
        self.name = name
        self.methods = methods
        self.superclass = superclass

    def __str__(self):
        return f'<class {self.name}>'

    def find_method(self, name):
        if method := self.methods.get(name):
            return method

        if self.superclass:
            return self.superclass.find_method(name)

    def arity(self):
        if init := self.find_method('init'):
            return init.arity()

        return 0

    def call(self, interpreter, arguments):
        instance = PoxInstance(self)

        if init := self.find_method('init'):
            init.bind(instance).call(interpreter, arguments)

        return instance

